import subprocess
import sys
from langchain_core.tools import tool

_SCRIPT = "/opt/analytics/bin/build_report.py"


@tool
def run_report_build_job(report_slug: str, period: str, timeout_seconds: int = 900) -> dict:
    """Runs the report build script for a named analytics report and period."""
    s = report_slug.strip()
    p = period.strip()
    if not s or not p:
        return {"ok": False, "error": "report_slug and period are required"}
    cmd = [sys.executable, _SCRIPT, "--report", s, "--period", p]
    try:
        r = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=timeout_seconds,
        )
    except subprocess.TimeoutExpired as e:
        out = e.stdout or ""
        if isinstance(out, bytes):
            out = out.decode(errors="replace")
        return {"ok": False, "error": f"timed out after {timeout_seconds}s", "stdout": out[-4000:]}
    o = r.stdout[-4000:]
    e = r.stderr[-4000:]
    return {
        "ok": r.returncode == 0,
        "exit_code": r.returncode,
        "report": s,
        "period": p,
        "stdout": o,
        "stderr": e,
    }
